function validate([n, x]) {
  if (typeof n !== 'string' || n.length < 1 || n.length > 100000) return 'n needs 1 to 10^5 characters.';
  if (!/^-?[1-9]+$/.test(n)) return "n is an optional '-' followed by digits 1 to 9.";
  if (!Number.isInteger(x) || x < 1 || x > 9) return 'x is a digit from 1 to 9.';
  return null;
}

