function maxValue(n, x) {
  const digit = String(x);
  const negative = n[0] === '-';
  let i = negative ? 1 : 0;

  while (i < n.length) {
    if (negative && n[i] > digit) {
      break;
    }
    if (!negative && n[i] < digit) {
      break;
    }
    i++;
  }
  return n.slice(0, i) + digit + n.slice(i);
}

