function maxValue(n, x) {
  // Try every insertion point and keep the numerically largest result.
  const start = n[0] === '-' ? 1 : 0;
  let best = null;
  for (let pos = start; pos <= n.length; pos++) {
    const candidate = n.slice(0, pos) + x + n.slice(pos);
    if (best === null || BigInt(candidate) > BigInt(best)) best = candidate;
  }
  return best;
}

