function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const negative = rand() < 0.5;
  const length = size === 'large' ? int(9000, 9999) : int(1, 7);
  // Sometimes draw digits from a narrow band around x so ties and near-ties appear.
  const x = int(1, 9);
  const narrow = rand() < 0.4;
  const lo = narrow ? Math.max(1, x - 1) : 1;
  const hi = narrow ? Math.min(9, x + 1) : 9;
  let text = negative ? '-' : '';
  for (let i = 0; i < length; i++) text += String(int(lo, hi));
  return [text, x];
}
